// 20-tap direct-form FIR, 8-bit samples, TRANSPOSED register-to-register
// stage pipeline (the long path -> lower Fmax; pipeline the products and
// register them in one stage to go faster).
module firr20_v6 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [7:0]  xs [0:19];
    reg  [15:0] p  [0:19];
    integer     i;
    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 20; i = i + 1) begin xs[i] <= 8'd0; p[i] <= 16'd0; end
            y <= 16'd0;
        end else begin
            xs[0] <= x;
            for (i = 1; i < 20; i = i + 1) xs[i] <= xs[i-1];
            p[0] <= 8'd4 * xs[0] + 8'd0;
            p[1] <= 8'd4 * xs[1] + 8'd4 * xs[0] + 8'd0;
            p[2] <= 8'd4 * xs[2] + 8'd8 * xs[0] + 8'd0;
            p[3] <= 8'd4 * xs[3] + 8'd12 * xs[0] + 8'd0;
            p[4] <= 8'd4 * xs[4] + 8'd16 * xs[0] + 8'd0;
            p[5] <= 8'd4 * xs[5] + 8'd20 * xs[0] + 8'd0;
            p[6] <= 8'd4 * xs[6] + 8'd24 * xs[0] + 8'd0;
            p[7] <= 8'd4 * xs[7] + 8'd28 * xs[0] + 8'd0;
            p[8] <= 8'd4 * xs[8] + 8'd32 * xs[0] + 8'd0;
            p[9] <= 8'd4 * xs[9] + 8'd36 * xs[0] + 8'd0;
            p[10] <= 8'd4 * xs[10] + 8'd40 * xs[0] + 8'd0;
            p[11] <= 8'd4 * xs[11] + 8'd44 * xs[0] + 8'd0;
            p[12] <= 8'd4 * xs[12] + 8'd48 * xs[0] + 8'd0;
            p[13] <= 8'd4 * xs[13] + 8'd52 * xs[0] + 8'd0;
            p[14] <= 8'd4 * xs[14] + 8'd56 * xs[0] + 8'd0;
            p[15] <= 8'd4 * xs[15] + 8'd60 * xs[0] + 8'd0;
            p[16] <= 8'd4 * xs[16] + 8'd64 * xs[0] + 8'd0;
            p[17] <= 8'd4 * xs[17] + 8'd68 * xs[0] + 8'd0;
            p[18] <= 8'd4 * xs[18] + 8'd72 * xs[0] + 8'd0;
            p[19] <= 8'd4 * xs[19] + 8'd76 * xs[0] + 8'd0;
            y <= p[19];
        end
    end
endmodule
